MOD = 10**9 + 7

def solve(n, m, labyrinth):
    directions = [(0, 1), (1, 0)]
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    queue = deque([(0, 0)])
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if labyrinth[nx][ny] == 'R':
                    while 0 <= nx + dx < n and 0 <= ny + dy < m and labyrinth[nx + dx][ny + dy] == 'R':
                        nx += dx
                        ny += dy
                    if 0 <= nx + dx < n and 0 <= ny + dy < m:
                        nx += dx
                        ny += dy
                if dp[nx][ny] == 0:
                    dp[nx][ny] = dp[x][y]
                    queue.append((nx, ny))
                else:
                    dp[nx][ny] = (dp[nx][ny] + dp[x][y]) % MOD

    return dp[n-1][m-1]

