def find_spec_prod_part(n, com):
    if n <= 1:
        return "Invalid input"
    if len(factorint(n)) == 1:
        return "It is a prime number"

    def score(partition):
        return sum(factor**exp for factor, exp in partition) * len(partition)

    def partition(n, k):
        if k == 1:
            return [[n]]
        if n == 0:
            return [[]]
        result = []
        for i in range(1, n + 1):
            for p in partition(n - i, k - 1):
                if p and i < p[-1]:
                    continue
                result.append([i] + p)
        return result

    max_partition = []
    max_score = float('-inf')
    min_partition = []
    min_score = float('inf')

    for k in range(2, n + 1):
        parts = partition(n, k)
        for part in parts:
            part_factors = factorint(n)
            for factor in part:
                if factor in part_factors:
                    part_factors[factor] -= 1
                    if part_factors[factor] == 0:
                        del part_factors[factor]
            current_score = score(part)
            if current_score > max_score:
                max_score = current_score
                max_partition = part
            if current_score < min_score:
                min_score = current_score
                min_partition = part

    if com == 'max':
        return [max_partition, max_score]
    elif com == 'min':
        return [min_partition, min_score]
