import math

def find_spec_prod_part(n, com):
    if n < 2:
        return "Invalid input"
    if is_prime(n):
        return "It is a prime number"

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    def prime_factors(n):
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    def score(partition):
        return sum([x[0]**x[1] for x in collections.Counter(partition).items()]) * len(partition)

    def partition(n, k):
        if k == 1:
            return [[n]]
        result = []
        for i in range(1, n // k + 1):
            for p in partition(n - i, k - 1):
                result.append([i] + p)
        return result

    factors = prime_factors(n)
    partitions = partition(n, len(factors))
    scores = [(p, score(p)) for p in partitions]

    if com == 'max':
        return max(scores, key=lambda x: x[1])
    elif com == 'min':
        return min(scores, key=lambda x: x[1])
    else:
        return "Invalid command"

