        "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90
    }
    scales = {
        "thousand": 1000, "million": 1000000
    }

    def parse_chunk(chunk):
        total = 0
        current = 0
        for word in chunk.split():
            if word in units:
                current += units[word]
            elif word in tens:
                current += tens[word]
            elif word in scales:
                total += current * scales[word]
                current = 0
        return total + current

    chunks = string.replace(" and ", " ").split()
    result = 0
    for chunk in chunks:
        result += parse_chunk(chunk)
    return result

