    special_teens = ['十', '十一', '十二', '十三', '十四', '十五', '十六', '十七', '十八', '十九']

    def number_to_chinese(num):
        if num == 0:
            return '零'
        result = []
        i = 0
        zero_flag = False
        while num > 0:
            digit = num % 10
            if digit == 0:
                if not zero_flag and result and result[-1] != '零':
                    result.append('零')
                zero_flag = True
            else:
                if zero_flag:
                    result.append('零')
                    zero_flag = False
                if i == 1 and digit == 1:
                    result.append(special_teens[0])
                else:
                    result.append(digits[digit] + units[i])
            num //= 10
            i += 1
        return ''.join(result[::-1])

    if n == 0:
        return '零'
    elif n < 0:
        return '负' + number_to_chinese(-n)
    else:
        integer_part, decimal_part = divmod(n, 1)
        integer_chinese = number_to_chinese(integer_part)
        decimal_chinese = number_to_chinese(int(decimal_part * 100000000))
